    contents = []
    while end < len(sql):
        if sql[end] == "'":
            if end + 1 < len(sql) and sql[end + 1] == "'":
                contents.append("'")
                end += 2
            else:
                break
        else:
            contents.append(sql[end])
            end += 1

    if end >= len(sql) or sql[end] != "'":
        raise SQLSyntaxError("Unterminated string literal")

    return ''.join(contents), end + 1

def tokenize(sql: str) -> list[Token]:
    """Convert ``sql`` into tokens, always ending with one EOF token.

    Raises:
        SQLSyntaxError: on an unterminated string or an unknown character.
    """
    tokens = []
    pos = 0

    while pos < len(sql):
        if sql[pos].isspace():
            pos += 1
            continue

        if is_identifier_start(sql[pos]):
            start_pos = pos
            while pos < len(sql) and is_identifier_char(sql[pos]):
                pos += 1

            ident = sql[start_pos:pos]
            if ident.upper() in KEYWORDS:
                tokens.append(Token(TokenType.KEYWORD, ident.upper(), start_pos))
            else:
                tokens.append(Token(TokenType.IDENTIFIER, ident, start_pos))

        elif sql[pos].isdigit():
            start_pos = pos
            while pos < len(sql) and sql[pos].isdigit():
                pos += 1

            tokens.append(Token(TokenType.INTEGER, sql[start_pos:pos], start_pos))

        elif sql[pos] == "'":
            start_pos = pos
            content, pos = read_string_literal(sql, pos)
            tokens.append(Token(TokenType.STRING, content, start_pos))

        else:
            for op in OPERATORS:
                if sql.startswith(op, pos):
                    tokens.append(Token(TokenType.OPERATOR, op, pos))
                    pos += len(op)
                    break
            else:
                raise SQLSyntaxError(f"Unknown character: {sql[pos]}")

    tokens.append(Token(TokenType.EOF, "", len(sql)))
    return tokens
